// ============================================================
// THUMBNAIL CARD (always highlighted variant)
// ============================================================
const ThumbCard: React.FC<{
  thumb: Thumb;
  index: number;
  width: number;
  highlightProgress: number;
}> = ({ thumb, width, highlightProgress, index }) => {
  const frame = useCurrentFrame();
  const driftY = ambientDrift(frame, 1.5, 90 + index * 7, `thumb-${index}-y`);
  const driftX = ambientDrift(frame, 1, 110 + index * 5, `thumb-${index}-x`);

  const hlBorder = `${interpolate(highlightProgress, [0, 1], [1, 3])}px solid ${COLORS.orange}`;
  const glowOpacity = highlightProgress * 0.55;
  const liftScale = 1 + highlightProgress * 0.04;

  const previewH = width * (9 / 16);
  const metaH = width * 0.22;
  const totalH = previewH + metaH;

  return (
    <div
      style={{
        position: "relative",
        width,
        height: totalH,
        transform: `translate(${driftX}px, ${driftY}px) scale(${liftScale})`,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: -20,
          background: COLORS.orange,
          filter: "blur(40px)",
          opacity: glowOpacity,
          borderRadius: 32,
          mixBlendMode: "screen",
          pointerEvents: "none",
        }}
      />

      <div
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          background: COLORS.card,
          border: hlBorder,
          borderRadius: 14,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          boxShadow: `0 24px 64px rgba(248,102,6,${0.25 * highlightProgress})`,
        }}
      >
        <ThumbPreview thumb={thumb} width={width} height={previewH} />

        <div
          style={{
            flex: 1,
            display: "flex",
            gap: width * 0.03,
            padding: `${width * 0.035}px ${width * 0.04}px`,
          }}
        >
          <div
            style={{
              width: width * 0.075,
              height: width * 0.075,
              borderRadius: "50%",
              background: `linear-gradient(135deg, ${HUE_MAP[thumb.hue].a}, ${HUE_MAP[thumb.hue].b})`,
              flexShrink: 0,
            }}
          />
          <div
            style={{
              flex: 1,
              display: "flex",
              flexDirection: "column",
              minWidth: 0,
            }}
          >
            <div
              style={{
                fontFamily: "Inter, sans-serif",
                fontSize: width * 0.038,
                fontWeight: 600,
                color: COLORS.text,
                letterSpacing: "-0.01em",
                lineHeight: 1.2,
                overflow: "hidden",
                display: "-webkit-box",
                WebkitLineClamp: 2,
                WebkitBoxOrient: "vertical",
              }}
            >
              {thumb.title}
            </div>
            <div
              style={{
                marginTop: width * 0.008,
                fontFamily: "Inter, sans-serif",
                fontSize: width * 0.027,
                fontWeight: 500,
                color: COLORS.textMuted,
                letterSpacing: "-0.005em",
              }}
            >
              {thumb.channel}
            </div>
            <div
              style={{
                fontFamily: "Inter, sans-serif",
                fontSize: width * 0.025,
                fontWeight: 500,
                color: COLORS.textSubtle,
              }}
            >
              {thumb.views}
            </div>
          </div>
        </div>

        <svg
          width={width * 0.35}
          height={width * 0.35}
          viewBox="0 0 100 100"
          style={{
            position: "absolute",
            right: -1,
            bottom: -1,
            opacity: 0.18 * highlightProgress,
            pointerEvents: "none",
