};

// ============================================================
// TOPIC NODE
// ============================================================
const TopicNode: React.FC<{
  cx: number;
  cy: number;
  size: number;
  progress: number;
}> = ({ cx, cy, size, progress }) => {
  const frame = useCurrentFrame();
  const driftY = ambientDrift(frame, 2, 70, "topic-y");
  const breathe = 1 + Math.sin(frame / 24) * 0.015;

  const ringPulse = (Math.sin(frame / 18) + 1) / 2;

  return (
    <div
      style={{
        position: "absolute",
        left: cx - size / 2,
        top: cy - size / 2 + driftY,
        width: size,
        height: size,
        opacity: progress,
        transform: `scale(${interpolate(progress, [0, 1], [0.6, breathe])})`,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: -size * 0.3,
          background: COLORS.orange,
          filter: `blur(${size * 0.18}px)`,
          opacity: 0.35 * progress,
          borderRadius: "50%",
          mixBlendMode: "screen",
        }}
      />

      <div
        style={{
          position: "absolute",
          inset: -size * 0.08 - ringPulse * size * 0.04,
          borderRadius: "50%",
          border: `2px solid ${COLORS.orange}`,
          opacity: (1 - ringPulse) * 0.6 * progress,
        }}
      />

      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: "50%",
          background: `radial-gradient(circle at 30% 30%, ${COLORS.orange}, ${COLORS.orangeDeep})`,
          border: `${size * 0.012}px solid ${COLORS.orange}`,
          boxShadow: `0 ${size * 0.06}px ${size * 0.2}px rgba(248,102,6,0.5)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexDirection: "column",
          padding: size * 0.08,
        }}
      >
        <svg
          width={size * 0.42}
          height={size * 0.42}
          viewBox="0 0 100 100"
          style={{ marginBottom: size * 0.04 }}
        >
          {[0, 60, 120, 180, 240, 300].map((deg) => {
            const rad = (deg * Math.PI) / 180;
            const x2 = 50 + Math.cos(rad) * 32;
            const y2 = 50 + Math.sin(rad) * 32;
            return (
              <line
                key={deg}
                x1={50}
                y1={50}
                x2={x2}
                y2={y2}
                stroke="#fff"
                strokeWidth={2.5}
                strokeLinecap="round"
                opacity={0.85}
              />
            );
          })}
          {[0, 60, 120, 180, 240, 300].map((deg) => {
            const rad = (deg * Math.PI) / 180;
            const x = 50 + Math.cos(rad) * 32;
            const y = 50 + Math.sin(rad) * 32;
            return (
              <circle
                key={`n-${deg}`}
                cx={x}
                cy={y}
                r={6}
                fill="#fff"
                opacity={0.95}
              />
            );
          })}
          <circle cx={50} cy={50} r={11} fill="#fff" />
          <circle cx={50} cy={50} r={5} fill={COLORS.orangeDeep} />
        </svg>

        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: size * 0.085,
            fontWeight: 800,
            color: "#fff",
            letterSpacing: "0.16em",
            textTransform: "uppercase",
            textShadow: "0 2px 6px rgba(0,0,0,0.3)",
          }}
        >
          Topic
        </div>
      </div>
    </div>
  );
};

// ============================================================
// CONNECTING LINE — symmetric S-curve from card right-edge to topic left-edge
// ============================================================
const ConnectionLine: React.FC<{
  from: { x: number; y: number };
  to: { x: number; y: number };
  progress: number;
  index: number;
}> = ({ from, to, progress }) => {
  const frame = useCurrentFrame();

  // Symmetric horizontal S-curve: control points pulled horizontally toward center.
  // Every line uses the SAME shape recipe, just different endpoints — guarantees symmetry.
  const dx = to.x - from.x;
  const cp1x = from.x + dx * 0.5;
  const cp1y = from.y;
  const cp2x = to.x - dx * 0.5;
  const cp2y = to.y;

  const pathD = `M ${from.x} ${from.y} C ${cp1x} ${cp1y} ${cp2x} ${cp2y} ${to.x} ${to.y}`;

  // Approximate path length for stroke-dash reveal
  const straightLen = Math.sqrt(dx * dx + (to.y - from.y) * (to.y - from.y));
  const pathLength = straightLen * 1.2;
  const dashOffset = interpolate(progress, [0, 1], [pathLength, 0]);

  // Traveling pulse along the line
  const pulseCycle = ((frame * 0.6) % 60) / 60;
  const pulseOpacity = progress >= 1 ? Math.sin(pulseCycle * Math.PI) * 0.7 : 0;
  // Approximate pulse position along the bezier (linear interp is close enough visually)
  const t = pulseCycle;
  const mt = 1 - t;
  const pulseX =
    mt * mt * mt * from.x +
    3 * mt * mt * t * cp1x +
    3 * mt * t * t * cp2x +
    t * t * t * to.x;
  const pulseY =
    mt * mt * mt * from.y +
    3 * mt * mt * t * cp1y +
    3 * mt * t * t * cp2y +
    t * t * t * to.y;

  return (
    <>
      <path
        d={pathD}
        stroke={COLORS.orange}
        strokeWidth={10}
        fill="none"
        strokeLinecap="round"
        strokeDasharray={pathLength}
        strokeDashoffset={dashOffset}
        opacity={0.25 * progress}
        style={{ filter: "blur(8px)" }}
      />
      <path
        d={pathD}
        stroke={COLORS.orange}
        strokeWidth={2.5}
        fill="none"
        strokeLinecap="round"
        strokeDasharray={pathLength}
        strokeDashoffset={dashOffset}
        opacity={0.9 * progress}
      />
      {progress >= 0.95 && (
        <circle
          cx={pulseX}
          cy={pulseY}
          r={5}
          fill={COLORS.orange}
          opacity={pulseOpacity}
          style={{ filter: "blur(0.5px)" }}
        />
      )}
      <circle
        cx={from.x}
        cy={from.y}
        r={6}
        fill={COLORS.orange}
        opacity={progress}
      />
    </>
  );
};

// ============================================================
// BACKGROUND
// ============================================================
const Background: React.FC = () => <AbsoluteFill />;

// ============================================================
// SCENE
// ============================================================
const SceneMain: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // SMALLER cards so top + bottom don't get cut off by ambient drift / glow
  const cardW = width * 0.17;
  const previewH = cardW * (9 / 16);
  const metaH = cardW * 0.22;
  const cardH = previewH + metaH;

  // Tighter stacking, anchored so the 3 cards + their glow halos all fit
  const stackGap = height * 0.035;
  const stackH = cardH * 3 + stackGap * 2;
  const stackTop = (height - stackH) / 2;
  const stackLeft = width * 0.1;

  // Topic node — smaller too, to balance
  const topicSize = Math.min(width * 0.18, height * 0.32);
  const topicCx = width * 0.72;
  const topicCy = height / 2;

  // Card right-edge midpoints (where each line departs)
  const cardCenters = [0, 1, 2].map((i) => ({
    x: stackLeft + cardW,
    y: stackTop + i * (cardH + stackGap) + cardH / 2,
  }));

  // Topic node connection points — all on the LEFT edge of the node,
  // symmetric vertical offsets so the three lines mirror the card stack.
  // Middle line goes dead-center; top and bottom mirror each other.
  const topicLeftX = topicCx - topicSize / 2;
  const verticalSpread = topicSize * 0.28;
  const topicConnectionPoints = [
    { x: topicLeftX + topicSize * 0.04, y: topicCy - verticalSpread },
    { x: topicLeftX, y: topicCy },
    { x: topicLeftX + topicSize * 0.04, y: topicCy + verticalSpread },
  ];

  const HL_START = 17;
  const HL_STAGGER = 4;
  const breathePulse = Math.sin(frame / 22) * 0.08;

  const LINE_START = HL_START + HL_STAGGER * 2 + 14;
  const LINE_STAGGER = 8;

  const TOPIC_START = LINE_START + 10;
  const topicProgress = springIn(frame, fps, TOPIC_START, "LIQUID");

  return (
    <AbsoluteFill>
      <Background />

      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          inset: 0,
          pointerEvents: "none",
        }}
      >
        {cardCenters.map((from, i) => {
          const lineProgress = springIn(
            frame,
            fps,
            LINE_START + i * LINE_STAGGER,
            "LIQUID"
          );
          return (
            <ConnectionLine
              key={i}
              from={from}
              to={topicConnectionPoints[i]}
              progress={lineProgress}
              index={i}
            />
          );
        })}
      </svg>

      {THUMBS.map((thumb, i) => {
        const hlEntrance = springIn(frame, fps, HL_START + i * HL_STAGGER, "SNAPPY");
        const hlProgress = Math.min(1, hlEntrance + breathePulse * hlEntrance);
        return (
          <div
            key={thumb.id}
            style={{
              position: "absolute",
              left: stackLeft,
              top: stackTop + i * (cardH + stackGap),
              width: cardW,
              zIndex: 2,
            }}
          >
            <ThumbCard
              thumb={thumb}
              index={i}
              width={cardW}
              highlightProgress={hlProgress}
            />
          </div>
        );
      })}

      <TopicNode
        cx={topicCx}
        cy={topicCy}
        size={topicSize}
        progress={topicProgress}
      />
    </AbsoluteFill>
  );
};

// ============================================================
// MAIN COMPOSITION
// ============================================================
export const durationInFrames = 180;

const MainComposition: React.FC = () => {
  return <SceneMain />;
};

export default MainComposition;
